mapper.select:
SELECT r.id, u.household_id FROM recipes r JOIN users u ON u.id = r.user_id
WHERE r.group_id = #{groupId}
AND r.id = #{recipeId}AND r.slug = #{slug}

mapper.insert:
INSERT INTO households_to_recipes (id, household_id, recipe_id, last_made, created_at, update_at)
VALUES (#{linkId}, #{householdId}, #{recipeId}, #{lastMade}, #{now}, #{now})
ON CONFLICT (household_id, recipe_id) DO UPDATE SET last_made = #{lastMade}, update_at = #{now}
WHERE households_to_recipes.last_made IS NULL OR households_to_recipes.last_made != #{lastMade}
